\begin{aligned}
Y^{(i-1)} &= \frac{c_{i-1, 0}}{c_{i, 0}} \Big(Y^{(i)} + c_{i, 1}^2\,\nabla_{Y^{(i)}}\log p_i\!\big(Y^{(i)}\big)\Big) \\
